const EPS=[{"n":1,"jp":"夏の果ての島","cn":"夏之尽头的岛","en":"The Island at the Far End of Summer","date":"2021.07.16","ost":"少年少女 — 銀杏BOYZ","syn":"窗外只剩无声的漆黑。异能刚露面，学生会便立下规则接管校舍。朝风与希反抗遭罚后，希在天台撕碎课本跃入虚空，把长良一并拽进刺眼的碧海蓝天。","staff":"脚本・分镜・演出 夏目真悟 / 作画监督 长坂庆太","imgs":["01_07","01_01","01_08","01_09","01_13","01_02"],"pal":["#1383d1","#2d4e53","#95b1ab","#000000","#eee4dc","#81776c"],"bg":"#0c94de","fg":"#121416"},{"n":2,"jp":"エイリアンズ","cn":"异星人","en":"Aliens!","date":"2021.07.23","ost":"Broken Windows / Seagull — 落日飞车","syn":"众人被困在四面环海的孤岛，心安理得地享用瑞穗的猫送来的物资，却因她孤僻不合群，在接连失火后将她孤立。蓝紫色火焰吞没森林时，只有希游过海面朝她伸出手。","staff":"脚本・分镜 夏目真悟 / 演出 北川朋哉 / 作画监督 长泽礼子","imgs":["02_02","02_05","02_01","02_08","02_04","02_09"],"pal":["#2830a4","#0c2064","#067aef","#d0c8ae","#2b424a","#1d1813"],"bg":"#151865","fg":"#ffffff"},{"n":3,"jp":"下駄を履いたネコ","cn":"穿木屐的猫","en":"The Cat Who Wore Sandals","date":"2021.07.30","ost":"Summer Storm — VIDEOTAPEMUSIC","syn":"岛上陆续有学生化作漆黑剪影凝立不动，或凭空消失。瑞穗拉上沉默的长良四处查探，坦白猫的能力早在漂流前便已存在；长良却无意间掀开暗幕，一脚踏进另一个世界。","staff":"脚本 夏目真悟 / 分镜・演出 斋藤圭一郎 / 作画监督 刈谷畅秀","imgs":["03_04","03_02","03_05","03_07","03_10","03_03"],"pal":["#173321","#4a4d36","#897d61","#156ac3","#fdeda4","#f14a6d"],"bg":"#163221","fg":"#ffffff"},{"n":4,"jp":"偉大なるモンキー・ベースボール","cn":"伟大的猴子棒球","en":"The Great Monkey Baseball","date":"2021.08.06","ost":"Tune from diamond — ザ・なつやすみバンド","syn":"棒球帽在林间搭起球场，讲起“看不见的猴子棒球”。刚发觉自己能带世界跃迁的长良站上投手丘，对着王牌投出一记不按常理的球，白球直穿天际，撕开另一片新世界。","staff":"脚本 夏目真悟 / 分镜 川尻善昭 / 演出 イム・ガヒ / 作画监督 原科大树","imgs":["04_01","04_04","04_11","04_12","04_03","04_08"],"pal":["#f8e5d1","#076bd0","#34364f","#20231b","#d4b085"],"bg":"#066cd3","fg":"#ffffff"},{"n":5,"jp":"跳ぶ教室","cn":"跳跃的教室","en":"Leaping Classrooms","date":"2021.08.13","ost":"夜釣り — ミツメ","syn":"长良与希、朝风、瑞穗、拉吉塔尼在陌生世界间穿梭试探；留守避难所的学生则等来了亚希老师。她道出原世界早已办完毕业典礼，将众人的恐慌引向长良，校舍随之沉入黑暗。","staff":"脚本・分镜 夏目真悟 / 演出 石仓礼 / 作画监督 伊泽珠美 等","imgs":["05_02","05_03","05_11","05_16","05_09","05_13"],"pal":["#efefef","#07080c","#8c8d8f","#036ace","#f9e295"],"bg":"#040405","fg":"#ffffff"},{"n":6,"jp":"長いさよなら","cn":"漫长的告别","en":"The Long Goodbye","date":"2021.08.20","ost":"Let There Be Light Again — 落日飞车 / 剧中歌《旅立ちの日に》","syn":"闯入放映长良视角的“电影制片人”世界，窄缝却映出原世界的毕业典礼——众人不过是留在虚空里的复制品。希不肯低头，拉起长良向旧校舍道别；瑞穗则捡回会说话的黑狗山彦。","staff":"脚本・分镜 夏目真悟 / 演出 北川朋哉 / 作画监督 长泽礼子","imgs":["06_03","06_09","06_05","06_07","06_08","06_02"],"pal":["#e8e5df","#3e2310","#9e1331","#8c3c54","#f9d987","#b8853a"],"bg":"#3b210f","fg":"#ffffff"},{"n":7,"jp":"ロード・ブック","cn":"路书","en":"Road Book","date":"2021.08.27","ost":"Beacon — Ogawa & Tokoro","syn":"众人分道启程后，长良翻上山丘的单杠，跌进无限增筑的巨塔“巴别塔”。迷途者在此日复一日砌筑水泥以忘却来路，直到餐馆女孩姬提起流星坠落的房间，他才再度攀上单杠。","staff":"脚本 夏目真悟 / 分镜 川尻善昭 / 演出 松井健人 / 作画监督 八重樫洋平、喜友名阳","imgs":["07_12","07_01","07_03","07_11","07_13","07_07"],"pal":["#2c321d","#6f6034","#a29a98","#215ba6","#b9c6c2"],"bg":"#2c311d","fg":"#ffffff"},{"n":8,"jp":"笑い犬","cn":"笑犬","en":"Laughing Dog","date":"2021.09.03","ost":"Yamabiko's Theme / Kodama's Theme — 空中泥棒","syn":"夜幕与彩绘玻璃高塔下，山彦放起一盘旧录像带，讲出五千年前的往事：曾是孤僻少年的他漂入“祝祭之森”，遇见连接万物的少女木灵，直到披斗篷的“战争”踏进林间。","staff":"脚本 夏目真悟 / 分镜・演出・作画监督 斋藤圭一郎","imgs":["08_01","08_02","08_06","08_09","08_12","08_11"],"pal":["#242229","#b8826e","#915550","#e4ede8","#b4a9a3"],"bg":"#232127","fg":"#ffffff"},{"n":9,"jp":"この鮭茶漬け、鮭忘れてるニャ","cn":"这碗鲑鱼茶泡饭忘了放鲑鱼喵","en":"This Salmon Chazuke Is Missing Its Salmon Nya","date":"2021.09.10","ost":"Soft Oversight — Ogawa & Tokoro / ソウとセイジ — ミツメ","syn":"猫咪樱追查着“茶泡饭里消失的鲑鱼”，将众人引向无边雪原。本为一人的双胞胎庄与诚司正为谁的头发更多缠斗数千年，亚希老师却想夺走他们令世界倒流重来的力量。","staff":"脚本 夏目真悟 / 分镜 小嶋庆祐 / 演出 柏淳志 / 作画监督 小嶋庆祐、柏淳志","imgs":["09_01","09_03","09_04","09_05","09_09","09_10"],"pal":["#41475b","#c7d8f3"],"bg":"#c7d8f3","fg":"#121416"},{"n":10,"jp":"夏と修羅","cn":"夏与修罗","en":"Summer and the Demon","date":"2021.09.17","ost":"今日の歌 — カネヨリマサル","syn":"在拥挤的“最果车站”，骨折凭“独白”听尽路人心声，回望自己迎合朝风的怯懦，以及朝风在悬崖边没能留住希的那一瞬；岛上，长良与瑞穗的实验证实猫只带来复制品。","staff":"脚本・分镜 夏目真悟 / 演出 北川朋哉、松井健人 / 作画监督 原科大树","imgs":["10_02","10_06","10_07","10_08","10_03","10_01"],"pal":["#1673d4","#dce2dd","#2a4b6d","#836239","#492a18","#afaea1"],"bg":"#0e74d9","fg":"#ffffff"},{"n":11,"jp":"少年と海","cn":"少年与海","en":"The Young Man and the Sea","date":"2021.09.24","ost":"Lightship — ザ・なつやすみバンド","syn":"骨折来信捎来希的死讯——在不会终结的虚空里，有人“发明了死亡”。长良与瑞穗收拾遗物、将她的照片装框送别，重逢独行两千年的拉吉塔尼后，登上火箭启程。","staff":"脚本 夏目真悟 / 分镜・作画监督 久贝典史 / 演出 大野仁爱","imgs":["11_04","11_01","11_02","11_03","11_06","11_08"],"pal":["#7cb2e9","#24372f","#6894b3","#cacbce","#f2f5f7","#3a525b"],"bg":"#7cb2e9","fg":"#121416"},{"n":12,"jp":"二年間の休暇","cn":"两年间的假期","en":"Two Years' Vacation","date":"2021.10.01","ost":"スペア — ミツメ / サニーボーイ・ラプソディ — toe","syn":"朝风交出指南针选择留下，长良与瑞穗在崩解的斑斓世界间奔跑。回到两年后的阴雨开学日，除瑞穗外无人知晓漂流，路过的希也与他素不相识。房内指针空转，长良推门走入雨停后的街道。","staff":"脚本・分镜・演出 夏目真悟 / 作画监督 长坂庆太","imgs":["12_00","12_03","12_11","12_13","12_14","12_06"],"pal":["#b6b8b9","#42384f","#dde9de","#7897a6","#151514"],"bg":"#42374e","fg":"#ffffff"}];
const CAST=[["nagara","長良","市川蒼","観測者","习惯望向窗外、对什么都不抱期待，却在一次次跃迁后选择离开自己造出的世界。"],["nozomi","希","大西沙織","コンパス","归国转学生，眼里能看见远处唯一的光；哪怕得知自己只是复制品，也不肯在原地停步。"],["mizuho","瑞穂","悠木碧","ニャマゾン","带着祖母留下的三只猫，用快递纸箱划出领地；讨厌虚伪的抱团，却陪长良走到了最后。"],["asakaze","朝風","小林千晃","スローライト","操控重力的少年，嘴上厌恶被命令，却比谁都渴望被需要，最终留在自己主宰的世界。"],["rajidani","ラジダニ","後藤ヒロキ","ポケコン","拉吉塔尼。把漂流当作课题来推演的少年，造船独行两千年，始终清醒坦然。"],["hoshi","明星","内藤有海","Hope","左眼下有星形痣，能让他人看见想望的幻象；总是微笑退居幕后，听从脑海里的“声音”。"],["ponny","ポニー","佐藤はな","スイッチ","波妮。维持岛上秩序的学生会长，能对调触碰到的两件物品，行事倚重明星。"],["cap","キャップ","上田燿司","万能部室","棒球帽。能把无人空房变成任意场所，在漫长漂流里沉迷于看不见的猴子棒球。"],["hayato","はやと","山本祥太","ET","隼人。指尖只能像小手电般发光，性情温和，一直用笔记本认真记下众人的能力。"],["syanhai","上海","荻野佳奈","電気ビリビリ","说上海话的转学生，能操控电磁力；远离岛上的派系纷争，后来与骨折结伴漂流。"],["kosetsu","骨折","尾崎由香","モノローグ","左臂吊着绷带，能听见他人未曾说出口的心声，却困在讨好朝风的自卑里。"],["aki","あき先生","加隈亜衣","","亚希老师。在原世界假装温顺的教师，现身漂流后自称受神指派，借恐惧笼络学生与朝风。"],["yamabiko","やまびこ","津田健次郎","","山彦。瑞穗捡到的黑狗，曾是另一届漂流少年；失去木灵后化为犬形，在塔下守候五千年。"],["kodama","こだま","竹達彩奈","","木灵。五千年前“祝祭之森”的少女，能与万物共感相连，最终化作彩绘玻璃高塔。"],["2star","二つ星","松野太紀","","在巨塔“巴别塔”工地干活的开朗少年，教会初来乍到的长良用劳作打发漫长岁月。"],["hime","ヒメ","引坂理絵","","姬。“巴别塔”餐馆里的女孩，向长良说起流星坠落房间的传说，促使他再度动身。"],["senso","戦争","遊佐浩二","","披着破旧斗篷踏入森林的漂流者。并无恶意，却在抵达后终结了“祝祭之森”的平静。"],["sou","ソウとセイジ","古川慎","","庄与诚司。本是同一人，因头发多一根还是少一根的分歧裂成双胞胎，在雪原缠斗千年。"],["tora","とら・げん・さくら","","","虎、源、樱。祖母留给瑞穗的三只猫，“喵马逊”的送货员，送来的东西其实全是复制品。"]];
